using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer.Tools;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container resolves HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city by name.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London' or 'New York'")] string city)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/v1/current.json?key=demo&q={Uri.EscapeDataString(city)}");

        if (response is null)
            return "Unable to retrieve weather data.";

        return $"{response.Location.Name}, {response.Location.Country}: " +
               $"{response.Current.TempC}°C, {response.Current.Condition.Text}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 3);

        var response = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            $"/v1/forecast.json?key=demo&q={Uri.EscapeDataString(city)}&days={days}");

        if (response?.Forecast?.ForecastDays is null)
            return "Unable to retrieve forecast data.";

        var lines = response.Forecast.ForecastDays.Select(d =>
            $"{d.Date}: High {d.Day.MaxTempC}°C, Low {d.Day.MinTempC}°C — {d.Day.Condition.Text}");

        return string.Join("\n", lines);
    }
}

// Response models
public record WeatherResponse(
    [property: JsonPropertyName("location")] LocationInfo Location,
    [property: JsonPropertyName("current")] CurrentWeather Current);

public record LocationInfo(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("country")] string Country);

public record CurrentWeather(
    [property: JsonPropertyName("temp_c")] double TempC,
    [property: JsonPropertyName("condition")] WeatherCondition Condition);

public record WeatherCondition(
    [property: JsonPropertyName("text")] string Text);

public record ForecastResponse(
    [property: JsonPropertyName("forecast")] ForecastData Forecast);

public record ForecastData(
    [property: JsonPropertyName("forecastday")] List<ForecastDay> ForecastDays);

public record ForecastDay(
    [property: JsonPropertyName("date")] string Date,
    [property: JsonPropertyName("day")] DayInfo Day);

public record DayInfo(
    [property: JsonPropertyName("maxtemp_c")] double MaxTempC,
    [property: JsonPropertyName("mintemp_c")] double MinTempC,
    [property: JsonPropertyName("condition")] WeatherCondition Condition);

